makeMtLab(document.getElementById("lab-l14"),{id:"l14",scenarios:[{"label": "Ví dụ: P của ca mẫu", "note": "Chu kỳ lý tưởng × tổng đếm / thời gian chạy.", "steps": [{"t": "Dữ liệu", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Đại lượng<\/th><th scope=\"col\">Giá trị<\/th><\/tr><\/thead><tbody><tr><td>Chu kỳ lý tưởng<\/td><td>2,0 s<\/td><\/tr><tr><td>Tổng đếm<\/td><td>10 500<\/td><\/tr><tr><td>Thời gian chạy<\/td><td>23 400 s<\/td><\/tr><\/tbody><\/table>"}, {"t": "P", "html": "<p class=\"mt-calc\">21 000 / 23 400 ≈ <b>0,8974<\/b><\/p>", "ask": {"q": "P bằng bao nhiêu?", "o": ["0,8974", "1,1143", "0,8667"], "a": 0}}]}, {"label": "Ví dụ: Dạng tốc độ", "note": "Tốc độ thực chia tốc độ lý tưởng.", "steps": [{"t": "Tốc độ thực", "html": "<p class=\"mt-calc\">10 500 / 23 400 ≈ 0,4487 hộp/s<\/p>"}, {"t": "Chia 0,5 hộp/s", "html": "<p class=\"mt-calc\">0,4487 / 0,5 ≈ 0,8974<\/p>", "say": "<p>Hai dạng cho cùng kết quả.<\/p>"}]}, {"label": "Ví dụ: Tổn thất hiệu suất bằng phút", "note": "Thời gian chạy − thời gian chạy tịnh.", "steps": [{"t": "Chạy 390 phút, chạy tịnh 350 phút", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Tầng<\/th><th scope=\"col\">Phút<\/th><\/tr><\/thead><tbody><tr><td>Thời gian chạy<\/td><td>390<\/td><\/tr><tr><td>Thời gian chạy tịnh<\/td><td>350<\/td><\/tr><\/tbody><\/table>"}, {"t": "Hiệu số", "html": "<p class=\"mt-calc\">390 − 350 = <b>40 phút<\/b> mất do dừng ngắn và chạy chậm<\/p>", "ask": {"q": "Tổn thất hiệu suất bao nhiêu phút?", "o": ["40", "60", "10"], "a": 0}}]}, {"label": "Bẫy: Chu kỳ lý tưởng đặt 2,5 s", "note": "Đặt theo trung bình thực tế thay vì thiết kế.", "steps": [{"t": "P mới", "html": "<p class=\"mt-calc\">2,5 × 10 500 / 23 400 ≈ 1,1218<\/p>", "ask": {"q": "P > 1 nghĩa là gì?", "o": ["Máy rất tốt", "Chu kỳ lý tưởng đặt sai"], "a": 1}}, {"t": "Sửa: dùng chu kỳ thiết kế 2,0 s", "html": "<p class=\"mt-calc\">P ≈ 0,8974<\/p>", "say": "<p>MES cảnh báo khi P > 1 thay vì cắt về 1.<\/p>"}]}, {"label": "Lỗi: Bộ đếm đếm hai lần", "note": "Cảm biến thấy cả thân hộp và nắp.", "steps": [{"t": "Tổng đếm 21 000", "html": "<p class=\"mt-calc\">P = 2,0 × 21 000 / 23 400 ≈ 1,7949<\/p>"}, {"t": "Sửa ở PLC", "html": "<p class=\"mt-calc\">Đếm theo cạnh lên, có lọc thời gian tối thiểu giữa hai hộp<\/p>", "say": "<p>P vượt xa 1 thường là lỗi đếm.<\/p>"}]}]});
